function helpGuide(){section("Οδηγός παιχνιδιού");screen.append(button("‹ Πίσω",moreBack,"secondary"));const intro=card();intro.classList.add("guide-intro");intro.append(el("h3","Πώς λειτουργούν οι Προβλέψεις"),el("p","Ιδιωτικό παιχνίδι με δωρεάν εικονικές μάρκες. Δεν αγοράζονται, δεν εξαργυρώνονται και δεν έχουν χρηματική αξία.","muted"));const groups=[
["🎯","Γεγονότα και ψηφοφορία",["Επίλεξε αποτέλεσμα σε διαθέσιμο γεγονός. Οι ώρες ανοίγματος και επιβεβαίωσης εμφανίζονται στην εφαρμογή και εξαρτώνται από το είδος γεγονότος.","Όταν ανοίξει η επιβεβαίωση, δήλωσε το πραγματικό αποτέλεσμα. Η ψήφος καταχωρίζεται μία φορά."]],
["🎟️","Δελτίο και αποδόσεις",["Οι επιλογές συγκεντρώνονται στο Δελτίο. Μία απάντηση αποτελεί μονό δελτίο· περισσότερες διαφορετικές ερωτήσεις αποτελούν συνδυαστικό δελτίο. Μπορείς να αφαιρέσεις επιλογές πριν από την οριστική καταχώριση. Κάθε υποβολή καταχωρίζει ένα δελτίο. Μια λανθασμένη επιλογή μηδενίζει την επιστροφή του συνδυαστικού δελτίου· οι ακυρωμένες επιλογές αντιμετωπίζονται σύμφωνα με τους κανόνες πληρωμής.","Ποντάρισμα 10–1.000 διαθέσιμες μάρκες. Η πιθανή συνολική επιστροφή εμφανίζεται πριν την καταχώριση, με ανώτατο όριο 10.000. Το ιστορικό δείχνει εκκρεμή και ολοκληρωμένα δελτία."]],
["👤","Προφίλ και συλλογή",["Το προφίλ παρουσιάζει την ταυτότητα, την περιουσία, την εμφάνιση και τα αποκτημένα αντικείμενα. Τα αντικείμενα είναι εικονικά.","Η εμπειρία εμφανίζεται ως XP (10 ανά καταγεγραμμένη ημέρα δραστηριότητας). Από την εμφάνισή μου μπορείς να προεπισκοπήσεις και να εφαρμόσεις διαθέσιμα χρώματα, τίτλους, πλαίσια, φόντα, εφέ και τρόπαια.","Οι κατηγορίες περιουσίας δείχνουν τα αντικείμενα που απέκτησες. Τα ιδιωτικά δώρα δεν εμφανίζονται δημόσια."]],
["🛍️","Κατάστημα και δώρα",["Δες τις κατηγορίες, την τιμή και την περιγραφή κάθε αντικειμένου. Οι αγορές χρησιμοποιούν μόνο διαθέσιμες μάρκες που επιτρέπονται για αγορές, όχι δεσμευμένες ή δανεικές.","Τα ιδιωτικά δώρα εμφανίζονται μόνο στον παραλήπτη μαζί με τον αποστολέα. Τα επιτεύγματα δείχνουν τι έχει ήδη ξεκλειδωθεί."]],
["🏆","Κατάταξη και μέλη",["Η κατάταξη έχει προβολές περιουσίας, κερδών, εβδομάδας και μήνα. Μπορείς να ανοίξεις το δημόσιο προφίλ άλλου μέλους από τη λίστα Μελών.","Η περιουσία και τα διαθέσιμα δεν είναι απαραίτητα το ίδιο ποσό."]],
["🏦","Τράπεζα",["Στα Περισσότερα → Τράπεζα φαίνονται διαθέσιμες και δεσμευμένες μάρκες, δάνεια και επόμενη πίστωση 1.000 μαρκών.","Αιτήματα δανείου 50–300 μάρκες, όταν υπάρχουν έως 100 διαθέσιμες για ποντάρισμα και επιτρέπεται από το εβδομαδιαίο όριο. Το εβδομαδιαίο όριο δανεισμού και χορήγησης είναι 300 αντίστοιχα.","Εξόφληση πριν τη Δευτέρα χωρίς τόκο. Στη λήξη εφαρμόζεται 10% τόκος, με στρογγυλοποίηση προς τα πάνω ανά δάνειο."]],
["🃏","Blackjack",["Στόχος: σύνολο κοντά στο 21 χωρίς υπέρβαση. Οι φιγούρες αξίζουν 10, ο άσος 1 ή 11. Η τράπεζα μένει στο 17.","Φύλλο: παίρνεις φύλλο. Μένω: ολοκληρώνεις το χέρι. Double: διπλασιάζεις το ποντάρισμα και παίρνεις ένα φύλλο. Split: χωρίζεις δύο ίδια φύλλα μία φορά. Οι άσοι μετά από Split παίρνουν ένα φύλλο.","Συνολική επιστροφή: νίκη 2×, ισοπαλία 1×, φυσικό 21 2,5× με στρογγυλοποίηση προς τα κάτω."]],
["🎰","Φρουτάκια",["Τρεις κύλινδροι και εννέα ορατές θέσεις. Μόνο τα τρία σύμβολα στη μεσαία γραμμή καθορίζουν το αποτέλεσμα. Οι πάνω και κάτω θέσεις είναι διακοσμητικές.","Οκτώ ισοπίθανα σύμβολα ανά κύλινδρο. Συνολική επιστροφή: δύο ίδια 2×, τρία ίδια 8×, τρία 7 16×, διαφορετικά 0."]],
["🛡️","Όρια Καζίνο",["Κοινό ημερήσιο όριο 500 μαρκών, έως 10 παρτίδες Blackjack και 20 περιστροφές. Αρχικό ποντάρισμα 10–100. Double και Split μετρούν στο κοινό όριο.","Ανανέωση στις 00:00 ώρα Ελλάδας. Τα αποτελέσματα καθορίζονται από τον server και δεν απαιτείται να χρησιμοποιήσεις όλο το διαθέσιμο όριο."]],
["🎁","Ημερήσια κλήρωση",["Κάθε ημέρα στις 12:00 ώρα Ελλάδας προβλέπεται αυτόματη κλήρωση 500 μαρκών για τα εγκεκριμένα μέλη, με ίσες πιθανότητες, χωρίς σύνδεση ή ποντάρισμα.","Ο νικητής και το ιστορικό εμφανίζονται στα Γεγονότα."]],
["📅","Μακροχρόνιες προβλέψεις",["Στις Παραιτήσεις επιλέγεις εργαζόμενο και διαθέσιμη περίοδο. Ποντάρισμα 10–100 μάρκες. Για σωστή πρόβλεψη προβλέπεται διπλάσια επιστροφή και μπόνους 2.000 μαρκών, σύμφωνα με τους κανόνες της ενότητας."]],
["⚙️","Ρυθμίσεις και λογαριασμός",["Οι ρυθμίσεις περιλαμβάνουν τις διαθέσιμες επιλογές ειδοποιήσεων. Η πρόσβαση απαιτεί εγκεκριμένο λογαριασμό και προσωπικό PIN.","Το Περισσότερα επιστρέφει ένα επίπεδο πίσω όταν βρίσκεσαι σε υποενότητα. Για πρόβλημα σύνδεσης ή λογαριασμού επικοινώνησε με τον διαχειριστή."]]
];for(const [icon,title,paragraphs] of groups){const d=el("details",undefined,"card guide-section"),s=el("summary"),label=el("span",icon,"guide-icon");label.setAttribute("aria-hidden","true");s.append(label,el("strong",title),el("span","⌄","guide-arrow"));d.append(s);const body=el("div",undefined,"guide-body");for(const p of paragraphs)body.append(el("p",p));d.append(body);screen.append(d);}}

